mapper.select:
SELECT username, real_name
FROM sys_user
WHERE deleted = 0
  AND tenant_id = #{tenantId}
  AND username IN #{u}
ORDER BY real_name, username

SELECT COALESCE(SUM(o.final_amount), 0)
FROM work_order w
JOIN orders o ON o.id=w.order_id AND o.tenant_id=#{tenantId} AND o.status='PAID'
WHERE w.deleted=0 AND w.tenant_id=#{tenantId}
  AND w.task_type='RENEWAL' AND w.status='DONE' AND w.complete_time IS NOT NULL
  AND w.complete_time >= #{start} AND w.complete_time < #{end}

  AND (w.current_owner_user IN
    #{x}
    OR (w.current_owner_user IS NULL AND w.owner_user IN
      #{x}))
